\begin{figure*}
\begin{tikzpicture}[node distance={10mm}, thick, main/.style = {draw, outer sep=0pt}]

\node (LCH) [main,xshift=2cm,yshift=2cm,text width=3cm] {\tiny Locally-compact Hausdorff nilspaces, Def \ref{def:top-nil-open-maps-version}};

\node (Gr-cong) [main,right=6.5cm of LCH,text width=3cm]  {\tiny Groupable congruences and fiber transitive filtrations, Defs \ref{def:groupable}, \ref{def:ft-fil}.};

\node (Basic) [main,xshift=0cm,yshift=0cm,text width=1.5cm]  {\tiny Basics: Thm \ref{thm:factor-of-lch-nil} };
\draw[] (LCH) to (Basic);

\node (Lie-nil) [main,xshift=2cm,yshift=-1cm,text width=1.5cm]  {\tiny Lie-fibered nilspaces, Def \ref{def:lcfr-nil} };
\draw[dashed] (LCH) to (Lie-nil);

\node (Ext-lift) [main,xshift=5cm,yshift=0cm,text width=2.7cm]  {\tiny Extensions, Def \ref{def:ext-lch-nil}, and lifts of translations, Prop \ref{prop:cont-lift-of-trans}.};
\draw[] (LCH) to (Ext-lift);

\node (Algebraic-aspects) [main,xshift=8.5cm,yshift=-1cm,text width=2.7cm]  {\tiny Algebraic aspects, Lems \ref{lem:group-cong-to-factors} and \ref{lem:cong-equi}.};
\draw[] (Gr-cong) to (Algebraic-aspects);

\node (Top-aspects) [main,xshift=15cm,yshift=-1cm,text width=2cm]  {\tiny Topological aspects, Def \ref{def:oldclosed}, Thm \ref{thm:coset-quot-closed}.};
\draw[] (Gr-cong) to (Top-aspects);

\node (free-nil) [main,xshift=2cm,yshift=-4.5cm,text width=1.7cm]  {\tiny Free nilspaces $F$, Def \ref{def:free-nil}.};
\draw[dashed] (Lie-nil) to (free-nil);

\node (open-map) [main,xshift=0cm,yshift=-3.5cm,text width=1.5cm]  {\tiny Open mapping theorem, Thm \ref{thm:open-mapping-thm}.};
\draw[] (Lie-nil) to (open-map);

\node (tran-polish) [main,xshift=4.3cm,yshift=-3.5cm,text width=2cm]  {\tiny $\tran(\ns)$ is Polish, Thm \ref{thm:trans-group-polish}. };
\draw[] (Lie-nil) to (tran-polish);

\node (lift-lemmas) [main,xshift=0cm,yshift=-6.5cm,text width=2cm]  {\tiny Lifting lemma, Thm \ref{thm:lift-mor-cfr-ab-gr}. };
\draw[] (free-nil) to (lift-lemmas);

\node (trans-free) [main,xshift=4cm,yshift=-7cm,text width=3cm]  {\tiny Description of $\hom(F,F')$, Lem \ref{lem:binompoly}, and $\tran(F)$ is Lie, Thm \ref{thm:decrip-trans-group}. };
\draw[] (free-nil) to (trans-free);

\node (ext-split) [main,xshift=7.5cm,yshift=-5cm,text width=2.7cm]  {\tiny \textbf{Extensions of free nilspaces are split extensions, Thm \ref{thm:splitext}.}};
\draw[dotted,-stealth] (Ext-lift) to (ext-split);
\draw[dotted,-stealth] (trans-free) to (ext-split);

\node (quo-free) [main,xshift=7.5cm,yshift=-8cm,text width=2.7cm]  {\tiny \textbf{\textsc{cfr} nilspaces are quotients of free nilspaces, Thm \ref{thm:gpcongrep}.}};
\draw[dotted,-stealth] (ext-split) to (quo-free);
\draw[dotted,-stealth] (trans-free) to [out=270, in=180] (quo-free);
\draw[dotted,-stealth] (Gr-cong) to [out=240, in=40] (quo-free);

\node (free-cong) [main,xshift=11.7cm,yshift=-4cm,text width=2cm]  {\tiny Free groupable congruences, Def \ref{def:free-group-cong}, Prop \ref{prop:embeb-strong-good}.};
\draw[dashed] (Gr-cong) to  (free-cong);

\node (Dou-cos) [main,xshift=14.7cm,yshift=-4cm,text width=2.7cm]  {\tiny Double-coset nilspaces, Lem \ref{lem:nil-pair-good-fil}.};
\draw[dashed] (Gr-cong) to (Dou-cos);

\node (inv-nilsystem) [main,xshift=11cm,yshift=-7.5cm,text width=2.7cm]  {\tiny \textbf{New proof of the inverse theorem from \cite{J&T} for the $U^3$-norm, Thm \ref{thm:jam-tao}.}};
\draw[dotted,-stealth] (quo-free) to (inv-nilsystem);
\draw[dotted,-stealth] (free-cong) to (inv-nilsystem);

\node (cpct-nil) [main,xshift=11cm,yshift=-10.5cm,text width=2.7cm]  {\tiny \textbf{$k$-step compact nilspaces as double coset spaces, Thm \ref{thm:cpct-nil-as-dou-coset}.}};
\draw[dotted,-stealth] (quo-free) to (cpct-nil);
\draw[dotted,-stealth] (Dou-cos) to [out=210, in=30] (cpct-nil);

\node (reg-inv-dou-cos) [main,xshift=14.5cm,yshift=-12cm,text width=2.7cm]  {\tiny \textbf{Inverse theorem with double-coset spaces, Thm \ref{thm:inv-double-coset-intro}; and with higher-order lattice actions, Thm \ref{thm:inv-high-ord-latti-intro}.}};
\draw[dotted,-stealth] (quo-free) to [out=210, in=210] (reg-inv-dou-cos);
\draw[dotted,-stealth] (Dou-cos) to (reg-inv-dou-cos);
\end{tikzpicture}
\vspace*{-1cm}\caption{\footnotesize{Diagram of the paper showing the main results and their interrelations. If two boxes are joined by a line, then the results referred to in the upper box need to be read first. If the line is dashed, then the objects referred to in the lower box form a special case of those in the upper box. A dotted line with an arrow indicates that the result at the head of the arrow strongly relies on the results at the tail of the arrow. The main results of the paper are in boldface.}}
\end{figure*}

